<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'||getenv('EL_PREPROD_LOCAL')!=='1')throw new RuntimeException('Local dev1 only');
$root=dirname(__DIR__);$data=json_decode(file_get_contents($root.'/release-input.json'),true,512,JSON_THROW_ON_ERROR);$report=['environment'=>'dev1','routes'=>[],'errors'=>[]];
foreach($data['places'] as $entry){$slug=$entry['destination']['slug'];foreach(['es'=>'','en'=>'/en','pt-BR'=>'/pt-br'] as $locale=>$prefix){
 $expectedImages=1+count(array_filter($entry['places'],fn($x)=>$x['publication_status']==='published'&&isset($x['image'])));$path=$prefix.'/lugares/'.$slug.'/';$ch=curl_init('http://127.0.0.1'.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30]);$html=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$doc=new DOMDocument();libxml_use_internal_errors(true);$doc->loadHTML($html?:'');$xp=new DOMXPath($doc);$heading=trim($xp->evaluate('string(//h1)'));$lang=$doc->documentElement->getAttribute('lang');$images=[];$bad=[];
 foreach($xp->query('//img[@src]') as $img){$src=$img->getAttribute('src');$urlpath=parse_url($src,PHP_URL_PATH);if(!str_starts_with($urlpath?:'','/assets/destinos/'))continue;$images[]=$src;$ch=curl_init('http://127.0.0.1'.$urlpath);curl_setopt_array($ch,[CURLOPT_NOBODY=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15]);curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($status!==200)$bad[]=$src;}
 $r=['path'=>$path,'http'=>$code,'lang'=>$lang,'heading'=>$heading,'expected_place_images'=>$expectedImages,'place_images'=>count($images),'broken_images'=>$bad,'canonical'=>$xp->evaluate('string(//link[@rel="canonical"]/@href)')];$report['routes'][]=$r;if($code!==200||!$heading||count($images)!==$expectedImages||$bad||stripos($html?:'','Fatal error')!==false)$report['errors'][]=$path;
}}
$c=require '/srv/state/private/config.php';$p=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$slugs=array_column(array_column($data['places'],'destination'),'slug');$q=$p->prepare('SELECT d.slug,d.publication_status,(SELECT COUNT(*) FROM points_of_interest x WHERE x.destination_id=d.id AND x.publication_status="published" AND x.poi_type="place") attractions,(SELECT COUNT(*) FROM points_of_interest x WHERE x.destination_id=d.id AND x.publication_status="published" AND x.poi_type="experience") experiences,(SELECT COUNT(*) FROM businesses b WHERE b.destination_id=d.id) businesses,(SELECT COUNT(*) FROM businesses b WHERE b.destination_id=d.id AND b.publication_status="published") published_businesses FROM destinations d WHERE d.slug IN ('.implode(',',array_fill(0,count($slugs),'?')).') ORDER BY d.slug');$q->execute($slugs);$report['places']=$q->fetchAll();$report['total_published_places']=(int)$p->query('SELECT COUNT(*) FROM destinations WHERE publication_status="published"')->fetchColumn();
if(count($report['places'])!==16||count(array_filter($report['places'],fn($x)=>$x['publication_status']==='published'))!==16)$report['errors'][]='Expected 16 published places';
file_put_contents($root.'/dev1-http-report.json',json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo json_encode(['routes'=>count($report['routes']),'errors'=>$report['errors'],'published_places'=>$report['total_published_places'],'batch_businesses'=>array_sum(array_column($report['places'],'businesses')),'batch_businesses_published'=>array_sum(array_column($report['places'],'published_businesses'))],JSON_PRETTY_PRINT)."\n";exit($report['errors']?1:0);
